<?php
declare(strict_types=1);
use PHPUnit\Framework\TestCase;
use gamboamartin\facturacion\controllers\{_base,controlador_fc_partida,controlador_fc_partida_nc,controlador_fc_partida_cp};
final class PartidaListadoTest extends TestCase {
 protected function setUp():void {$_GET=[];require_once __DIR__.'/soporte_partida.php';foreach(['_base','_ctl_partida','controlador_fc_partida','controlador_fc_partida_nc','controlador_fc_partida_cp'] as $file)require_once RAIZ_REPOSITORIO_PRUEBAS.'/controllers/'.$file.'.php';}
 public function testFacturaConfiguraUnaSolaTabla():void {$c=new controlador_fc_partida(new Pruebas\Partida\ConexionSinRed());self::assertTrue($c->lista_get_data);self::assertSame(1,$c->inicializaciones);self::assertSame(['fc_partida_id','com_producto_codigo','com_producto_descripcion','fc_factura_descripcion','fc_partida_cantidad','fc_partida_valor_unitario','fc_partida_descuento','fc_partida_n_traslados','fc_partida_n_retenidos'],array_keys($c->config_recibida->columns));}
 public function testFacturaConservaFiltrosDeRelacion():void {$c=new controlador_fc_partida(new Pruebas\Partida\ConexionSinRed());self::assertSame(['fc_partida.id','fc_partida.codigo','fc_factura.descripcion','com_producto.descripcion','fc_partida.cantidad','fc_partida.valor_unitario','fc_partida.descuento'],$c->config_recibida->filtro);}
 public function testNotaCreditoConservaConstructorAnterior():void {$c=new controlador_fc_partida_nc(new Pruebas\Partida\ConexionSinRed());self::assertFalse($c->lista_get_data);self::assertSame([],(array)$c->config_recibida);self::assertSame(1,$c->inicializaciones);}
 public function testComplementoConservaConstructorAnterior():void {$c=new controlador_fc_partida_cp(new Pruebas\Partida\ConexionSinRed());self::assertFalse($c->lista_get_data);self::assertSame([],(array)$c->config_recibida);self::assertSame(1,$c->inicializaciones);}
 public function testBaseSinParametroMantieneDefault():void {$c=new _base(new gamboamartin\system\html_controler(new gamboamartin\template\html()),new Pruebas\Partida\ConexionSinRed(),new base\orm\modelo(new Pruebas\Partida\ConexionSinRed()));self::assertSame([],(array)$c->config_recibida);self::assertFalse($c->lista_get_data);}
 public function testBaseRecibeConfiguracionSinMutarla():void {$cfg=(object)['columns'=>['ficticia'=>['titulo'=>'Ficticia']],'filtro'=>['tabla.id']];$copy=serialize($cfg);$c=new _base(new gamboamartin\system\html_controler(new gamboamartin\template\html()),new Pruebas\Partida\ConexionSinRed(),new base\orm\modelo(new Pruebas\Partida\ConexionSinRed()),config_datatable:$cfg);self::assertSame($cfg,$c->config_recibida);self::assertSame($copy,serialize($cfg));}
 public function testFacturaConservaConexionRutasYGenerador():void {$p=new Pruebas\Partida\ConexionSinRed();$paths=(object)['generales'=>'FICTICIO'];$c=new controlador_fc_partida($p,paths_conf:$paths);self::assertSame($paths,$c->rutas_recibidas);self::assertSame(['nuevo_traslado_bd',$p,-1,'fc_partida'],$c->obj_link->ultima);self::assertSame('ENLACE_FICTICIO',$c->link_fc_traslado_alta_bd);}
 public function testContextoFacturaNoActivaTablaDePartida():void {$_GET=['seccion'=>'fc_factura','accion'=>'modifica','registro_id'=>42];$before=$_GET;$c=new controlador_fc_partida(new Pruebas\Partida\ConexionSinRed());self::assertFalse($c->lista_get_data);self::assertSame([],(array)$c->config_recibida);self::assertSame($before,$_GET);self::assertSame(1,$c->inicializaciones);}
 public function testContextoDirectoPartidaActivaTabla():void {$_GET=['seccion'=>'fc_partida','accion'=>'lista'];$c=new controlador_fc_partida(new Pruebas\Partida\ConexionSinRed());self::assertTrue($c->lista_get_data);self::assertCount(9,$c->config_recibida->columns);}
}
